mapper.select:
select  from takeout_address a
left join sys_user u on u.user_id = a.user_id
where a.del_flag = '0'
and a.address_id = #{addressId}
and a.user_id = #{userId}
and a.receiver_name like concat('%', #{receiverName}, '%')
and a.receiver_phone = #{receiverPhone}
order by a.is_default desc, a.update_time desc, a.address_id desc
